function i(e){if(!e)return"-";const t=new Date(e);if(Number.isNaN(t.getTime())||t.getFullYear()<2e3)return"-";const n=r=>String(r).padStart(2,"0");return`${t.getFullYear()}-${n(t.getMonth()+1)}-${n(t.getDate())} ${n(t.getHours())}:${n(t.getMinutes())}`}function o(e){if(!e)return"";const t=e instanceof Date?e:new Date(e);if(Number.isNaN(t.getTime()))return"";const n=r=>String(r).padStart(2,"0");return`${t.getFullYear()}-${n(t.getMonth()+1)}-${n(t.getDate())} ${n(t.getHours())}:${n(t.getMinutes())}:${n(t.getSeconds())}`}function a(e){if(e==null||e==="")return"-";const t=Number(e);return Number.isFinite(t)?t.toLocaleString("zh-CN"):String(e)}function u(e){const t=Number(e)||0;return t<1e3?`${Math.round(t)}ms`:`${(t/1e3).toFixed(2)}s`}function s(e,t=90){const n=String(e||"").replace(/\s+/g," ").trim();return n.length<=t?n:`${n.slice(0,t)}...`}export{u as a,a as b,s as c,i as f,o as t};
